{"path": "task.py", "content": "def bit_pack(*args, **kwargs):
    # Determine the source of boolean values
    if len(args) == 1 and isinstance(args[0], (list, tuple)):
        source = args[0]
    else:
        source = args
    # Convert source to a list of booleans
    if isinstance(source, bool):
        bools = [source]
    else:
        try:
            bools = list(source)
        except TypeError:
            bools = [source]
    # Create bit values (1 for True, 0 for False)
    bits = [1 if b else 0 for b in bools]
    # Pack bits into bytes, most-significant-bit first
    result = bytearray()
    byte = 0
    pos = 7  # start at MSB
    for b in bits:
        if b:
            byte |= (1 << pos)
        pos -= 1
        if pos < 0:
            result.append(byte)
            byte = 0
            pos = 7
    if byte != 0:
        result.append(byte)
    return bytes(result)"}

